selector_to_html = {"a[href=\"#course-overview\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Course overview<a class=\"headerlink\" href=\"#course-overview\" title=\"Link to this heading\">#</a></h2><p>This course develops the foundations of Lebesgue measure and integration and the <span class=\"math notranslate nohighlight math-fallback\" data-math-prerendered=\"\" data-tex=\"L^p\" data-math-display=\"inline\" data-math-speech=\"L to the p-th power\" role=\"math\" aria-label=\"Math: L to the p-th power. Original TeX: L^p\"><mjx-container class=\"MathJax math-svg\" jax=\"SVG\" overflow=\"overflow\" aria-hidden=\"true\" focusable=\"false\"><svg style=\"vertical-align: 0;\" xmlns=\"http://www.w3.org/2000/svg\" width=\"2.533ex\" height=\"1.548ex\" role=\"img\" focusable=\"false\" viewBox=\"0 -684 1119.7 684\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><defs><path id=\"MJX-1-NCM-I-1D43F\" d=\"M520 667C520 678 513 683 500 683L354 680L223 683C208 684 200 676 200 659C200 652 203 647 209 646C218 645 226 644 231 644C262 643 279 641 284 640C289 639 292 636 292 631C292 629 291 623 288 613L156 82C150 60 140 47 125 42C119 40 101 39 70 39C49 39 39 31 39 15C39 5 49 0 70 0L527 0C552 0 554 0 561 19L639 233C642 240 643 245 643 248C643 258 638 263 627 263C617 263 612 254 607 240C588 191 570 154 555 131C518 75 455 39 363 39L270 39C259 39 252 39 249 40C242 40 239 42 239 45C239 47 241 54 244 67L377 601C383 624 396 637 415 642C421 643 442 644 478 644C506 644 520 644 520 667Z\"></path><path id=\"MJX-1-NCM-I-1D45D\" d=\"M355 442C311 442 269 419 228 373C217 419 186 442 137 442C96 442 66 409 45 344C35 311 30 292 30 286C30 277 35 272 46 272C51 272 54 273 57 275C62 284 65 291 66 298C84 374 107 412 134 412C152 412 161 398 161 371C161 356 159 339 154 321L44-118C35-151 34-155-5-155C-23-155-32-163-32-178C-32-189-26-194-15-194C0-194 52-191 67-191C86-191 146-194 165-194C180-194 187-186 187-170C187-160 178-155 159-155C141-155 114-156 114-144C114-131 155 26 159 43C179 6 209-13 249-13C314-13 371 20 421 87C467 148 490 213 490 280C490 367 438 442 355 442M352 412C391 412 411 382 411 323C411 296 405 260 394 215C371 128 342 71 307 42C286 25 267 16 248 16C219 16 199 29 188 56C179 77 174 92 174 100L225 309C230 331 248 354 276 377C304 400 329 412 352 412Z\"></path></defs><g stroke=\"currentColor\" fill=\"currentColor\" stroke-width=\"0\" transform=\"scale(1,-1)\"><g data-mml-node=\"math\" data-latex=\"L^p\"><g data-mml-node=\"msup\" data-latex=\"L^p\"><g data-mml-node=\"mi\" data-latex=\"L\"><use data-c=\"1D43F\" xlink:href=\"#MJX-1-NCM-I-1D43F\"></use></g><g data-mml-node=\"mi\" transform=\"translate(714,363) scale(0.707)\" data-latex=\"p\"><use data-c=\"1D45D\" xlink:href=\"#MJX-1-NCM-I-1D45D\"></use></g></g></g></g></svg></mjx-container></span> spaces that underpin modern analysis, partial differential equations, probability, and harmonic analysis.\nWe begin by identifying limitations of Riemann integration, then we construct measures - ways of describing how large a set is. We then develop measurable functions and use the notion of measure to construct the  Lebesgue integral, describing how large functions are.\nNext, we prove the major limit theorems for the Lebesgue integral, then and study normed spaces of integrable functions.\nThe final part of the course treats product measures and the Tonelli-Fubini theorems.</p>","a[href=\"#online-questions\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Online questions<a class=\"headerlink\" href=\"#online-questions\" title=\"Link to this heading\">#</a></h3><p>Online questions normally follow a lecture and are due by the start of our next class meeting. They focus on fluency with key vocabulary, examples, and basic deductions.</p>","a[href=\"#student-support\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Student support<a class=\"headerlink\" href=\"#student-support\" title=\"Link to this heading\">#</a></h3><p>Additional links are collected on the <a class=\"reference internal\" href=\"resources.html\"><span class=\"std std-doc\">resources page</span></a>.</p>","a[href=\"#letter-grades\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Letter grades<a class=\"headerlink\" href=\"#letter-grades\" title=\"Link to this heading\">#</a></h3><p>The following scale is the tentative baseline. If it changes, I will announce the revision in writing; a change will not make an already earned letter grade lower.</p>","a[href=\"#attendance-and-participation\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Attendance and participation<a class=\"headerlink\" href=\"#attendance-and-participation\" title=\"Link to this heading\">#</a></h3><p>Attendance is strongly encouraged but not graded, and there is no absence penalty.</p><p>If you need to miss class, use the posted notes, readings, online questions, homework, and other resources to keep up independently. Please keep track of course material, announcements, deadlines, and assessments.</p>","a[href=\"#id1\"]":"<table class=\"table\" id=\"id1\">\n<caption><span class=\"caption-text\">Course contents</span><a class=\"headerlink\" href=\"#id1\" title=\"Link to this table\">#</a></caption>\n<thead>\n<tr class=\"row-odd\"><th class=\"head text-left\"><p>Unit</p></th>\n<th class=\"head text-left\"><p>Main capability</p></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"row-even\"><td class=\"text-left\"><p>From Riemann integration to measure</p></td>\n<td class=\"text-left\"><p>Explain why a more flexible integral is needed; work with countability, null sets, outer measures, and the extended real line.</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p><span class=\"math notranslate nohighlight math-fallback\" data-math-prerendered=\"\" data-tex=\"\\sigma\" data-math-display=\"inline\" data-math-speech=\"sigma\" role=\"math\" aria-label=\"Math: sigma. Original TeX: \\sigma\"><mjx-container class=\"MathJax math-svg\" jax=\"SVG\" overflow=\"overflow\" aria-hidden=\"true\" focusable=\"false\"><svg style=\"vertical-align: -0.025ex;\" xmlns=\"http://www.w3.org/2000/svg\" width=\"1.292ex\" height=\"1ex\" role=\"img\" focusable=\"false\" viewBox=\"0 -431 571 442\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><defs><path id=\"MJX-4-NCM-I-1D70E\" d=\"M525 431L300 431C252 431 207 416 166 385C102 336 38 250 38 148C38 58 100-11 190-11C257-11 317 18 368 76C417 132 441 194 441 263C441 304 432 338 414 366L515 366C550 366 567 378 567 403C567 426 550 431 525 431M107 121C107 180 121 234 150 282C184 338 228 366 283 366C341 366 370 336 370 275C370 250 365 221 355 187C335 116 302 66 256 39C233 25 211 18 191 18C136 18 107 63 107 121Z\"></path></defs><g stroke=\"currentColor\" fill=\"currentColor\" stroke-width=\"0\" transform=\"scale(1,-1)\"><g data-mml-node=\"math\" data-latex=\"\\sigma\"><g data-mml-node=\"mi\" data-latex=\"\\sigma\"><use data-c=\"1D70E\" xlink:href=\"#MJX-4-NCM-I-1D70E\"></use></g></g></g></svg></mjx-container></span>-algebras and measures</p></td>\n<td class=\"text-left\"><p>Construct and analyze measurable spaces, Borel sets, measures, and Carathéodory-measurable sets; prove continuity properties of measures.</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Measurable functions and Lebesgue integration</p></td>\n<td class=\"text-left\"><p>Verify measurability, approximate nonnegative functions by simple functions, define the integral, and use monotone convergence, Fatou’s lemma, and dominated convergence.</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p><span class=\"math notranslate nohighlight math-fallback\" data-math-prerendered=\"\" data-tex=\"L^p\" data-math-display=\"inline\" data-math-speech=\"L to the p-th power\" role=\"math\" aria-label=\"Math: L to the p-th power. Original TeX: L^p\"><mjx-container class=\"MathJax math-svg\" jax=\"SVG\" overflow=\"overflow\" aria-hidden=\"true\" focusable=\"false\"><svg style=\"vertical-align: 0;\" xmlns=\"http://www.w3.org/2000/svg\" width=\"2.533ex\" height=\"1.548ex\" role=\"img\" focusable=\"false\" viewBox=\"0 -684 1119.7 684\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><defs><path id=\"MJX-1-NCM-I-1D43F\" d=\"M520 667C520 678 513 683 500 683L354 680L223 683C208 684 200 676 200 659C200 652 203 647 209 646C218 645 226 644 231 644C262 643 279 641 284 640C289 639 292 636 292 631C292 629 291 623 288 613L156 82C150 60 140 47 125 42C119 40 101 39 70 39C49 39 39 31 39 15C39 5 49 0 70 0L527 0C552 0 554 0 561 19L639 233C642 240 643 245 643 248C643 258 638 263 627 263C617 263 612 254 607 240C588 191 570 154 555 131C518 75 455 39 363 39L270 39C259 39 252 39 249 40C242 40 239 42 239 45C239 47 241 54 244 67L377 601C383 624 396 637 415 642C421 643 442 644 478 644C506 644 520 644 520 667Z\"></path><path id=\"MJX-1-NCM-I-1D45D\" d=\"M355 442C311 442 269 419 228 373C217 419 186 442 137 442C96 442 66 409 45 344C35 311 30 292 30 286C30 277 35 272 46 272C51 272 54 273 57 275C62 284 65 291 66 298C84 374 107 412 134 412C152 412 161 398 161 371C161 356 159 339 154 321L44-118C35-151 34-155-5-155C-23-155-32-163-32-178C-32-189-26-194-15-194C0-194 52-191 67-191C86-191 146-194 165-194C180-194 187-186 187-170C187-160 178-155 159-155C141-155 114-156 114-144C114-131 155 26 159 43C179 6 209-13 249-13C314-13 371 20 421 87C467 148 490 213 490 280C490 367 438 442 355 442M352 412C391 412 411 382 411 323C411 296 405 260 394 215C371 128 342 71 307 42C286 25 267 16 248 16C219 16 199 29 188 56C179 77 174 92 174 100L225 309C230 331 248 354 276 377C304 400 329 412 352 412Z\"></path></defs><g stroke=\"currentColor\" fill=\"currentColor\" stroke-width=\"0\" transform=\"scale(1,-1)\"><g data-mml-node=\"math\" data-latex=\"L^p\"><g data-mml-node=\"msup\" data-latex=\"L^p\"><g data-mml-node=\"mi\" data-latex=\"L\"><use data-c=\"1D43F\" xlink:href=\"#MJX-1-NCM-I-1D43F\"></use></g><g data-mml-node=\"mi\" transform=\"translate(714,363) scale(0.707)\" data-latex=\"p\"><use data-c=\"1D45D\" xlink:href=\"#MJX-1-NCM-I-1D45D\"></use></g></g></g></g></svg></mjx-container></span> spaces</p></td>\n<td class=\"text-left\"><p>Work with almost-everywhere equivalence, Hölder and Minkowski inequalities, completeness, modes of convergence, density, and basic duality estimates.</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Product measures and iterated integration</p></td>\n<td class=\"text-left\"><p>Set up product measure spaces and apply Tonelli’s and Fubini’s theorems with the correct hypotheses.</p></td>\n</tr>\n</tbody>\n</table>","a[href=\"#other-information\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Other information<a class=\"headerlink\" href=\"#other-information\" title=\"Link to this heading\">#</a></h2><h3>Accessibility and accommodations<a class=\"headerlink\" href=\"#accessibility-and-accommodations\" title=\"Link to this heading\">#</a></h3><p>If you have approved accommodations, please request your accommodation letter and contact me early so we can make arrangements in time. If you think you may need accommodations but have not yet set them up, the <a class=\"reference external\" href=\"https://cea.uark.edu/\">Center for Educational Access</a> can help. Temporary conditions can affect access too, so please reach out promptly when they arise.</p>","a[href=\"#weekly-hand-in-homework\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Weekly hand-in homework<a class=\"headerlink\" href=\"#weekly-hand-in-homework\" title=\"Link to this heading\">#</a></h3><p>Each homework is graded on a four-point scale. After feedback is returned, you have two days to resubmit; if the revision improves the solution, the higher score is recorded.</p><p>If you need more time, talk to me <strong>before the deadline</strong> so that we can work out an extension. We will handle unforeseen emergencies case by case.</p>","a[href=\"#academic-integrity\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Academic integrity<a class=\"headerlink\" href=\"#academic-integrity\" title=\"Link to this heading\">#</a></h2><p>We all share responsibility for creating a course environment built on honest work and learning. Please follow the <a class=\"reference external\" href=\"https://honesty.uark.edu/policy/\">University of Arkansas Academic Integrity Policy</a>; suspected violations are handled through the University process. Specific expectations for collaboration and artificial intelligence appear on the <a class=\"reference internal\" href=\"assignments/index.html\"><span class=\"std std-doc\">assignments page</span></a>.</p>","a[href=\"#id2\"]":"<table class=\"table\" id=\"id2\">\n<caption><span class=\"caption-text\">Grade weights</span><a class=\"headerlink\" href=\"#id2\" title=\"Link to this table\">#</a></caption>\n<thead>\n<tr class=\"row-odd\"><th class=\"head text-left\"><p>Component</p></th>\n<th class=\"head text-left\"><p>Weight</p></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Written hand-in homework</p></td>\n<td class=\"text-left\"><p>30%</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Online questions</p></td>\n<td class=\"text-left\"><p>10%</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Midterm</p></td>\n<td class=\"text-left\"><p>15%</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Final</p></td>\n<td class=\"text-left\"><p>15%</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p>Oral exam 1</p></td>\n<td class=\"text-left\"><p>15%</p></td>\n</tr>\n<tr class=\"row-odd\"><td class=\"text-left\"><p>Oral exam 2</p></td>\n<td class=\"text-left\"><p>15%</p></td>\n</tr>\n<tr class=\"row-even\"><td class=\"text-left\"><p><strong>Total</strong></p></td>\n<td class=\"text-left\"><p><strong>100%</strong></p></td>\n</tr>\n</tbody>\n</table>","a[href=\"#oral-exams\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Oral exams<a class=\"headerlink\" href=\"#oral-exams\" title=\"Link to this heading\">#</a></h3><p>For each oral exam, I will announce a topic list in advance. At the appointment you will receive two topics, choose one, and have 40 minutes to organize a board presentation. The presentation and follow-up discussion will last about 30 minutes. You should explain the motivation and precise statement, present the central proof, and discuss relevant examples, counterexamples, and limitations. Assessment emphasizes mathematical correctness, command of the ideas, and your ability to respond thoughtfully to questions.</p>","a[href=\"#communication-records-and-course-changes\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Communication, records, and course changes<a class=\"headerlink\" href=\"#communication-records-and-course-changes\" title=\"Link to this heading\">#</a></h2><p>Email is the best way to reach me with an individual question.</p><p>I will post course-wide announcements, grades, and updates in Blackboard, so please check your University email and Blackboard regularly.</p>","a[href=\"#learning-outcomes\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Learning outcomes<a class=\"headerlink\" href=\"#learning-outcomes\" title=\"Link to this heading\">#</a></h3><p>By the end of the course, you should be able to:</p>","a[href=\"#inclement-weather-and-emergencies\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Inclement weather and emergencies<a class=\"headerlink\" href=\"#inclement-weather-and-emergencies\" title=\"Link to this heading\">#</a></h3><p>We will follow University closure and inclement-weather decisions. If a closure prevents an exam, I will announce a new date through Blackboard and the course website. Please do not travel when conditions are unsafe.</p>","a[href=\"assignments/index.html\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Assignments<a class=\"headerlink\" href=\"#assignments\" title=\"Link to this heading\">#</a></h1><h2>Weekly written homework<a class=\"headerlink\" href=\"#weekly-written-homework\" title=\"Link to this heading\">#</a></h2><p>I will post written homework here approximately weekly. Submit through Gradescope using the links in <a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529398_1/outline/\">Blackboard &gt; Assignments &gt; Homework</a>.</p><p>You are encouraged to work in groups of up to three. Make one submission per group and list every group member clearly.</p>","a[href=\"#materials\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Materials<a class=\"headerlink\" href=\"#materials\" title=\"Link to this heading\">#</a></h3><p>My <a class=\"reference internal\" href=\"lecture-notes/index.html\"><span class=\"std std-doc\">lecture notes</span></a> are our main guide through the course. They may also link to explanatory videos or other freely available sources.</p><p>The principal reference is Luigi Ambrosio, Giuseppe Da Prato, and Andrea Mennucci, <em>Introduction to Measure Theory and Integration</em>, Publications of the Scuola Normale Superiore 10, Edizioni della Normale, 2011, <a class=\"reference external\" href=\"https://doi.org/10.1007/978-88-7642-386-4\">doi:10.1007/978-88-7642-386-4</a>.</p>","a[href=\"lecture-notes/index.html\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Lecture Notes<a class=\"headerlink\" href=\"#lecture-notes\" title=\"Link to this heading\">#</a></h1><p>Lecture notes will be added here as the semester progresses. Until a note is published, use the reading listed in the <a class=\"reference internal\" href=\"calendar.html#daily-lecture-log\"><span class=\"std std-ref\">daily lecture log</span></a>.</p>","a[href=\"#religious-observances-university-activities-and-other-excusable-conflicts\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Religious observances, University activities, and other excusable conflicts<a class=\"headerlink\" href=\"#religious-observances-university-activities-and-other-excusable-conflicts\" title=\"Link to this heading\">#</a></h3><p>Please email me as early as possible about religious observances, required University activities, military service, jury duty, documented illness, a family crisis, or another excusable conflict. For an exam conflict you can anticipate, at least one week’s notice is especially helpful. We will follow applicable University policies and deadlines.</p><p>If you have three or more final exams on one day, you may be able to reschedule one under <a class=\"reference external\" href=\"https://policies.uark.edu/academic/150020.php\">Academic Policy 1500.20</a>. If it involves this course, please make your request before the Registrar’s withdrawal deadline.</p>","a[href=\"#syllabus\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Syllabus<a class=\"headerlink\" href=\"#syllabus\" title=\"Link to this heading\">#</a></h1><h2>Course overview<a class=\"headerlink\" href=\"#course-overview\" title=\"Link to this heading\">#</a></h2><p>This course develops the foundations of Lebesgue measure and integration and the <span class=\"math notranslate nohighlight math-fallback\" data-math-prerendered=\"\" data-tex=\"L^p\" data-math-display=\"inline\" data-math-speech=\"L to the p-th power\" role=\"math\" aria-label=\"Math: L to the p-th power. Original TeX: L^p\"><mjx-container class=\"MathJax math-svg\" jax=\"SVG\" overflow=\"overflow\" aria-hidden=\"true\" focusable=\"false\"><svg style=\"vertical-align: 0;\" xmlns=\"http://www.w3.org/2000/svg\" width=\"2.533ex\" height=\"1.548ex\" role=\"img\" focusable=\"false\" viewBox=\"0 -684 1119.7 684\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><defs><path id=\"MJX-1-NCM-I-1D43F\" d=\"M520 667C520 678 513 683 500 683L354 680L223 683C208 684 200 676 200 659C200 652 203 647 209 646C218 645 226 644 231 644C262 643 279 641 284 640C289 639 292 636 292 631C292 629 291 623 288 613L156 82C150 60 140 47 125 42C119 40 101 39 70 39C49 39 39 31 39 15C39 5 49 0 70 0L527 0C552 0 554 0 561 19L639 233C642 240 643 245 643 248C643 258 638 263 627 263C617 263 612 254 607 240C588 191 570 154 555 131C518 75 455 39 363 39L270 39C259 39 252 39 249 40C242 40 239 42 239 45C239 47 241 54 244 67L377 601C383 624 396 637 415 642C421 643 442 644 478 644C506 644 520 644 520 667Z\"></path><path id=\"MJX-1-NCM-I-1D45D\" d=\"M355 442C311 442 269 419 228 373C217 419 186 442 137 442C96 442 66 409 45 344C35 311 30 292 30 286C30 277 35 272 46 272C51 272 54 273 57 275C62 284 65 291 66 298C84 374 107 412 134 412C152 412 161 398 161 371C161 356 159 339 154 321L44-118C35-151 34-155-5-155C-23-155-32-163-32-178C-32-189-26-194-15-194C0-194 52-191 67-191C86-191 146-194 165-194C180-194 187-186 187-170C187-160 178-155 159-155C141-155 114-156 114-144C114-131 155 26 159 43C179 6 209-13 249-13C314-13 371 20 421 87C467 148 490 213 490 280C490 367 438 442 355 442M352 412C391 412 411 382 411 323C411 296 405 260 394 215C371 128 342 71 307 42C286 25 267 16 248 16C219 16 199 29 188 56C179 77 174 92 174 100L225 309C230 331 248 354 276 377C304 400 329 412 352 412Z\"></path></defs><g stroke=\"currentColor\" fill=\"currentColor\" stroke-width=\"0\" transform=\"scale(1,-1)\"><g data-mml-node=\"math\" data-latex=\"L^p\"><g data-mml-node=\"msup\" data-latex=\"L^p\"><g data-mml-node=\"mi\" data-latex=\"L\"><use data-c=\"1D43F\" xlink:href=\"#MJX-1-NCM-I-1D43F\"></use></g><g data-mml-node=\"mi\" transform=\"translate(714,363) scale(0.707)\" data-latex=\"p\"><use data-c=\"1D45D\" xlink:href=\"#MJX-1-NCM-I-1D45D\"></use></g></g></g></g></svg></mjx-container></span> spaces that underpin modern analysis, partial differential equations, probability, and harmonic analysis.\nWe begin by identifying limitations of Riemann integration, then we construct measures - ways of describing how large a set is. We then develop measurable functions and use the notion of measure to construct the  Lebesgue integral, describing how large functions are.\nNext, we prove the major limit theorems for the Lebesgue integral, then and study normed spaces of integrable functions.\nThe final part of the course treats product measures and the Tonelli-Fubini theorems.</p>","a[href=\"resources.html\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Resources<a class=\"headerlink\" href=\"#resources\" title=\"Link to this heading\">#</a></h1><p>For every topic we cover, I will provide either lecture notes or a precise reading reference. The books below offer complementary treatments; you do not need to purchase them.</p>","a[href=\"#assessment\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Assessment<a class=\"headerlink\" href=\"#assessment\" title=\"Link to this heading\">#</a></h2><p><strong>Dropped assignments:</strong></p>","a[href=\"#accessibility-and-accommodations\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Accessibility and accommodations<a class=\"headerlink\" href=\"#accessibility-and-accommodations\" title=\"Link to this heading\">#</a></h3><p>If you have approved accommodations, please request your accommodation letter and contact me early so we can make arrangements in time. If you think you may need accommodations but have not yet set them up, the <a class=\"reference external\" href=\"https://cea.uark.edu/\">Center for Educational Access</a> can help. Temporary conditions can affect access too, so please reach out promptly when they arise.</p>","a[href=\"#course-organization\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Course organization<a class=\"headerlink\" href=\"#course-organization\" title=\"Link to this heading\">#</a></h2><p>In class, I will introduce new topics, develop proofs, and work through examples and applications with you.</p><p>I will assign weekly written homework. Fridays will usually emphasize problem solving, focused especially on appropriately marked problems from the homework.\nIf you give a substantially correct presentation of a problem designated for discussion, I may propose a grade immediately; if you are happy with that grade, you will not need to include that problem in the written submission.</p>","a[href=\"#written-exams\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Written exams<a class=\"headerlink\" href=\"#written-exams\" title=\"Link to this heading\">#</a></h3><p>There are two two-hour written exams: one midterm and one final. Each covers roughly half of the course topics. The midterm will be completed outside normal class hours; the final follows the Registrar’s schedule.</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "no-hover-preview"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
